    def _convert_v1725_to_standard(self, data):
        """将 V1725 结构化数组转换为标准列表格式"""
        channels = {}
        for row in data:
            ch = row['channel']
            if ch not in channels:
                channels[ch] = []
            channels[ch].append(row)

        max_ch = max(channels.keys())
        return [
            np.array(channels.get(ch, []), dtype=data.dtype)
            for ch in range(max_ch + 1)
        ]

